import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as i,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"MiniMax Agent 教程","description":"打开 agent.minimaxi.com，选 Lightning 或 Pro，发出第一个长程任务。这不是 MiniMax Code 桌面教程。","frontmatter":{"title":"MiniMax Agent 教程","description":"打开 agent.minimaxi.com，选 Lightning 或 Pro，发出第一个长程任务。这不是 MiniMax Code 桌面教程。","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/minimax-agent/minimax-agent.md","filePath":"zh/products/minimax-agent/minimax-agent.md","lastUpdated":1787107158000}'),r={name:"zh/products/minimax-agent/minimax-agent.md"};function o(l,t,d,s,h,m){return i(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="minimax-agent-教程" tabindex="-1">MiniMax Agent 教程 <a class="header-anchor" href="#minimax-agent-教程" aria-label="Permalink to &quot;MiniMax Agent 教程&quot;">​</a></h1><blockquote><p>目标：15 分钟内在网页工作台跑完一次可交付任务。</p><p>非目标：安装 MiniMax Code、配置工作区 / 终端 / 权限模式、解释模型内部。桌面端见 <a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">Code 欢迎页</a>。机制见 <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>能打开 <a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a>（国内）或 <a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">agent.minimax.io</a>（海外）。</li><li>一个 MiniMax 账号。登录按钮在产品页右上角，原文是「登录」/「Sign in」。</li><li>不需要本机仓库，不需要 CLI。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ol><li>分清 Agent 网页和 Code 桌面端。</li><li>按任务长度选 Lightning 或 Pro。</li><li>发出一个带交付物的任务，并知道何时改用 Agent Team 或技能市场。</li></ol><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><p>MiniMax Agent 是网页上的通用智能体。官方 <a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">靠谱</a> 用「靠谱的人」当设计标准，列了三块：</p><table tabindex="0"><thead><tr><th>标准</th><th>官方原文在说什么</th></tr></thead><tbody><tr><td>编程</td><td>更多组件和复杂跳转；模拟用户操作做测试；重视界面与交互</td></tr><tr><td>多模态</td><td>理解长文本、视频、音频、图片；内置生图、音频、视频</td></tr><tr><td>MCP</td><td>内置 MiniMax MCP；并写了 GitHub / GitLab / Slack / Figma 等办公扩展</td></tr></tbody></table><p>首页当前文案是「MiniMax，让工作更简单」，并提供 <strong>Agent 团队</strong> 开关和模型选择（2026-08-19 可见 MiniMax-M3）。</p><p>它<strong>不是</strong>：</p><ul><li>MiniMax Code（桌面端；<a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">welcome</a> 原文：「把对话、项目工作区、文件操作、终端、浏览器、技能、记忆和自动化任务放在同一个本地工作环境里」）</li><li>MiniMax Design / Hub（创作画布）</li><li>Hailuo、星野、Audio（见 <a href="./">学习地图</a>）</li></ul><h2 id="第一步-打开工作台" tabindex="-1">第一步：打开工作台 <a class="header-anchor" href="#第一步-打开工作台" aria-label="Permalink to &quot;第一步：打开工作台&quot;">​</a></h2><ol><li>打开 <a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a>。</li><li>点 <strong>登录</strong>。</li><li>用首页输入框描述目标。2026-08-19 首页可见快捷入口：<strong>视频生成</strong>、<strong>调研报告</strong>、<strong>文档</strong>、<strong>教育学习</strong>。</li><li>需要装桌面端时，首页有「下载桌面端」。注意：<a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">下载页</a> 当前标题是 <strong>MiniMax Code - 下载</strong>。那是桌面端品牌，不是本教程的下一步。</li></ol><p>海外站点步骤相同，入口换成 <a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">agent.minimax.io</a>，按钮原文是 <strong>Sign in</strong> / <strong>Download desktop</strong>。</p><h2 id="第二步-选-lightning-或-pro" tabindex="-1">第二步：选 Lightning 或 Pro <a class="header-anchor" href="#第二步-选-lightning-或-pro" aria-label="Permalink to &quot;第二步：选 Lightning 或 Pro&quot;">​</a></h2><p><a href="https://www.minimaxi.com/news/minimax-m2" target="_blank" rel="noreferrer">M2 新闻</a> 原文：</p><table tabindex="0"><thead><tr><th>模式</th><th>官方定位</th><th>官方举例</th></tr></thead><tbody><tr><td><strong>Lightning 高效模式</strong></td><td>高效极速版 Agent</td><td>对话问答 / 轻量级搜索 / 轻量级代码</td></tr><tr><td><strong>Pro 专业模式</strong></td><td>专业 agent 能力，复杂长程任务上最佳表现</td><td>深度研究 / 全栈开发 / PPT / 报告撰写 / 网页制作</td></tr></tbody></table><p>怎么选：</p><ul><li>一问一答、查一条资料、改一小段代码 → Lightning。</li><li>要一份带出处的报告、一套 PPT、一个可打开的网页、一次全栈交付 → Pro。</li><li>不确定就先 Lightning；交付物不够再开 Pro。不要把「所有任务都开 Pro」当成默认。</li></ul><p>两种模式是官方产品声明。界面上的具体开关文案以你登录后看到的为准；本页不臆造按钮路径。</p><h2 id="第三步-发出第一个任务" tabindex="-1">第三步：发出第一个任务 <a class="header-anchor" href="#第三步-发出第一个任务" aria-label="Permalink to &quot;第三步：发出第一个任务&quot;">​</a></h2><p>官方要求「show me the requirement」。把<strong>交付物</strong>写进第一句话。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我调研 MiniMax Agent 和 MiniMax Code 的官方区别。</span></span>
<span class="line"><span>只使用 minimaxi.com 与 agent.minimaxi.com 上的页面。</span></span>
<span class="line"><span>交付：</span></span>
<span class="line"><span>1. 一份 Markdown 对照表（产品、入口、适合做什么、不适合做什么）</span></span>
<span class="line"><span>2. 不超过 8 张幻灯片的 HTML 提纲，给前端工程师 internally share</span></span>
<span class="line"><span>不要写模型内部结构。</span></span></code></pre></div><p>发送后盯三件事：</p><ol><li>Agent 有没有先确认目标，而不是直接堆字。</li><li>引用是不是官方 URL。Verifier 思路见 <a href="https://agent.minimaxi.com/docs/techblog/agent-team.md" target="_blank" rel="noreferrer">Agent Team</a>：正式来源应尽量使用稳定 URL，搜索缓存只能当线索。</li><li>交付物能不能下载或打开。不要只收下一段聊天记录。</li></ol><p>第一个任务建议用 <strong>Pro</strong>。这是长程调研 + 双交付。</p><h2 id="第四步-复杂任务再开-agent-team" tabindex="-1">第四步：复杂任务再开 Agent Team <a class="header-anchor" href="#第四步-复杂任务再开-agent-team" aria-label="Permalink to &quot;第四步：复杂任务再开 Agent Team&quot;">​</a></h2><p><a href="https://agent.minimaxi.com/docs/techblog/agent-team.md" target="_blank" rel="noreferrer">Agent Team 技术文</a> 原文：用户仍然只发出一条消息；系统判断是否拆分、哪些角色并行、哪些结果必须验证。</p><p>三类角色（官方命名）：</p><ul><li><strong>Leader</strong>：把目标变成任务结构。</li><li><strong>Worker</strong>：执行子任务，工具 / 上下文 / 输出要求可以不同。</li><li><strong>Verifier</strong>：把「完成了」变成「可以交付」，和 Worker 是对抗关系。</li></ul><p>什么时候开 Team：</p><ul><li>要并行检索、交叉核验、再合成。</li><li>文档要过「能生产 → 能交付」（官方办公文档场景：Planner / Writer / Formatter / Evaluator）。</li><li>你在 IM 里等秒回，但任务本身要跑很久。官方写：主 Agent 先快速响应，后台拆分执行。</li></ul><p>什么时候不要开：</p><ul><li>改一处文案、查一个事实、生成一张图。官方自己说单 Agent 更便宜。</li><li>你还没写清验收标准。Team 会放大一个含糊目标。</li></ul><p>首页有 <strong>Agent 团队</strong> 开关。技术文还提到显式 <code>/team</code> 出现在桌面端 changelog 语境里；网页以你看到的开关为准，不要把 Code 斜杠命令抄过来当网页必经步骤。</p><h2 id="第五步-用技能市场扩展-而不是每次重写流程" tabindex="-1">第五步：用技能市场扩展，而不是每次重写流程 <a class="header-anchor" href="#第五步-用技能市场扩展-而不是每次重写流程" aria-label="Permalink to &quot;第五步：用技能市场扩展，而不是每次重写流程&quot;">​</a></h2><p>打开 <a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">agent.minimaxi.com/skills</a>。官方描述：「探索、安装和使用由开发者和社区构建的强大能力。」支持自定义创建或从 GitHub 导入。</p><p>2026-08-19 市场里能直接看到的官方技能包括：演示文稿、行业研究报告、DOCX、热点长文、图像提示词、股票分析、Excel、PowerPoint 等。<strong>技能名单会变</strong>，以市场页为准。</p><p>用法：</p><ol><li>先搜有没有现成技能，再开始长任务。</li><li>重复做过两次的流程，再考虑沉淀为自己的技能。Agent Team 文把「经验沉淀为记忆、Skill」写成 Team 的长期价值。</li><li>不要把技能市场和 Code 的插件市场混成一页。插件市场上线公告写在 Code 更新说明里。</li></ol><h2 id="计费-只抄两份官方原文" tabindex="-1">计费：只抄两份官方原文 <a class="header-anchor" href="#计费-只抄两份官方原文" aria-label="Permalink to &quot;计费：只抄两份官方原文&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>原文</th><th>怎么用</th></tr></thead><tbody><tr><td><a href="https://www.minimaxi.com/news/minimax-m2" target="_blank" rel="noreferrer">M2 新闻</a></td><td>「我们目前在免费提供 MiniMax Agent, 直到我们的服务器撑不住为止。」</td><td>这是发布当时的限时政策，不是长期 SLA</td></tr><tr><td><a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">技能市场</a></td><td>「统一计费：全面打通 Token Plan」</td><td>额度以账号内套餐页为准</td></tr><tr><td><a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">下载页</a></td><td>Plus ¥49 / Max ¥119 / Ultra ¥469</td><td>页面品牌是 MiniMax Code，不要写成 Agent 网页专用价</td></tr></tbody></table><p>登录后点首页的「查看套餐与价格」。本页不臆造 token 包大小。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>正确做法</th></tr></thead><tbody><tr><td>把 Agent 网页教程写成 Code CLI</td><td>本页停在浏览器。工作区 / 终端 / Coding 模式去 #72</td></tr><tr><td>所有任务都开 Pro 或 Team</td><td>短问答用 Lightning；Team 留给要验收的长程</td></tr><tr><td>把搜索摘要当出处</td><td>只要官方稳定 URL</td></tr><tr><td>把限时免费写成永远免费</td><td>链回套餐页</td></tr><tr><td>把 Hub 当成 Agent 的别名</td><td>Hub 当前落地页是 Design</td></tr><tr><td>写 MSA / 注意力细节</td><td>链 <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>场景配方：<a href="./minimax-agent-cookbook.html">Cookbook</a></li><li>入口与数据源：<a href="./minimax-agent-cheatsheet.html">速查表</a></li><li>名字：<a href="./minimax-agent-glossary.html">术语表</a></li><li>本机仓库：<a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">Code 欢迎页</a></li></ul>`,48)])])}const u=a(r,[["render",o]]);export{b as __pageData,u as default};
